-- ============================================================================
-- More global stack profiles (Phase 3D): Spring Boot and .NET, each with a React frontend and
-- PostgreSQL. Their definitions are grader/stacks/<key>.json (a test keeps them identical) and
-- their starters are templates/<key>.
-- ============================================================================

insert into public.stack_profiles (key, version, display_name, description, definition) values (
  'spring-react', 1, 'Spring Boot + React (Java 21, PostgreSQL)',
  'A Spring Boot 4 API on Java 21 with PostgreSQL, and a React frontend served by nginx. Lint with Checkstyle, tests with JUnit (mvn test), coverage with JaCoCo. Run with Docker Compose.',
  '{"detect": ["backend/pom.xml", "frontend/package.json", "compose.yaml"], "stages": {"lint": {"run": "cd backend && mvn -B -Dmaven.repo.local=/opt/hbe-tools/m2 -q checkstyle:check", "image": "maven:3.9-eclipse-temurin-21", "setup": "cd backend && mvn -B -Dmaven.repo.local=/opt/hbe-tools/m2 -q dependency:go-offline", "report": "text"}, "build": {"run": "docker compose build"}, "student_tests": {"run": "cd backend && mvn -B -Dmaven.repo.local=/opt/hbe-tools/m2 test", "image": "maven:3.9-eclipse-temurin-21", "setup": "cd backend && mvn -B -Dmaven.repo.local=/opt/hbe-tools/m2 -q dependency:go-offline", "report": "junit", "junit": "backend/target/surefire-reports"}, "coverage": {"run": "cd backend && mvn -B -Dmaven.repo.local=/opt/hbe-tools/m2 test", "image": "maven:3.9-eclipse-temurin-21", "setup": "cd backend && mvn -B -Dmaven.repo.local=/opt/hbe-tools/m2 -q dependency:go-offline", "format": "jacoco", "file": "backend/target/site/jacoco/jacoco.xml", "exclude": ["**/*Application.java"]}}, "services": {"backend": {"port": 8080, "health": "/health"}, "frontend": {"port": 3000, "health": "/"}}, "datastores": ["postgres:16"], "env_required": ["DATABASE_URL"], "ignore_paths": ["**/target/**", "**/node_modules/**", "**/dist/**", "**/package-lock.json"]}'::jsonb
);

insert into public.stack_profiles (key, version, display_name, description, definition) values (
  'dotnet-react', 1, '.NET + React (ASP.NET Core 10, PostgreSQL)',
  'An ASP.NET Core minimal API on .NET 10 with PostgreSQL, and a React frontend served by nginx. Lint with dotnet format, tests with xUnit (dotnet test), coverage with coverlet. Run with Docker Compose.',
  '{"detect": ["backend/Notes.slnx", "frontend/package.json", "compose.yaml"], "stages": {"lint": {"run": "export DOTNET_CLI_TELEMETRY_OPTOUT=1 DOTNET_NOLOGO=1; cd backend && dotnet format --verify-no-changes --no-restore", "image": "mcr.microsoft.com/dotnet/sdk:10.0", "setup": "export DOTNET_CLI_TELEMETRY_OPTOUT=1 DOTNET_NOLOGO=1; cd backend && dotnet restore --packages /opt/hbe-tools/nuget", "report": "text"}, "build": {"run": "docker compose build"}, "student_tests": {"run": "export DOTNET_CLI_TELEMETRY_OPTOUT=1 DOTNET_NOLOGO=1; cd backend && dotnet test --no-restore --logger ''junit;LogFilePath=/work/backend/TestResults/{assembly}.junit.xml''", "image": "mcr.microsoft.com/dotnet/sdk:10.0", "setup": "export DOTNET_CLI_TELEMETRY_OPTOUT=1 DOTNET_NOLOGO=1; cd backend && dotnet restore --packages /opt/hbe-tools/nuget", "report": "junit", "junit": "backend/TestResults"}, "coverage": {"run": "export DOTNET_CLI_TELEMETRY_OPTOUT=1 DOTNET_NOLOGO=1; cd backend && dotnet test --no-restore /p:CollectCoverage=true /p:CoverletOutputFormat=cobertura /p:CoverletOutput=/work/backend/coverage/", "image": "mcr.microsoft.com/dotnet/sdk:10.0", "setup": "export DOTNET_CLI_TELEMETRY_OPTOUT=1 DOTNET_NOLOGO=1; cd backend && dotnet restore --packages /opt/hbe-tools/nuget", "format": "cobertura", "file": "backend/coverage/coverage.cobertura.xml", "exclude": ["**/*Tests/**"]}}, "services": {"backend": {"port": 8080, "health": "/health"}, "frontend": {"port": 3000, "health": "/"}}, "datastores": ["postgres:16"], "env_required": ["DATABASE_URL"], "ignore_paths": ["**/bin/**", "**/obj/**", "**/node_modules/**", "**/dist/**", "**/package-lock.json"]}'::jsonb
);
